WITH valid AS (SELECT id, store_id, product_id, CEIL(units) AS units_whole FROM store_sales WHERE sale_date > DATE '2023-07-15'), joined AS (SELECT src.id, src.product_id, b.stock_qty FROM valid src LEFT JOIN products b ON src.product_id = b.id WHERE b.cost BETWEEN 400 AND 460), filtered AS (SELECT *, COALESCE(stock_qty, 0) AS stock_qty_filled FROM joined WHERE stock_qty < 187), scored AS (SELECT id, product_id, LEAD(stock_qty, 1) OVER (PARTITION BY product_id ORDER BY stock_qty_filled, id) AS next_stock_qty, COUNT(stock_qty) OVER (PARTITION BY product_id) AS product_id_count_stock_qty, ROW_NUMBER() OVER w_part AS row_seq FROM filtered WINDOW w_part AS (PARTITION BY product_id ORDER BY stock_qty_filled DESC, id)) SELECT dim.category, COUNT(*) AS cnt, MIN(a.next_stock_qty) AS min_next_stock_qty, MIN(a.product_id_count_stock_qty) AS min_product_id_count_stock_qty FROM scored a JOIN products dim ON a.product_id = dim.id GROUP BY ROLLUP (dim.category);
